using AcademyDesk.Api.Data; using AcademyDesk.Api.Domain.Entities; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace AcademyDesk.Api.Controllers;
[ApiController][Route("api/academies/{academyId:guid}/admin-work-items")]
public sealed class AdminWorkItemsController(AcademyDeskDbContext db):ControllerBase{
[HttpGet] public async Task<ActionResult> List(Guid academyId,string? status,CancellationToken t){var q=db.AdminWorkItems.AsNoTracking().Where(x=>x.AcademyId==academyId);if(!string.IsNullOrWhiteSpace(status))q=q.Where(x=>x.Status==status);return Ok(await q.OrderBy(x=>x.DueAtUtc).ThenByDescending(x=>x.Priority).ToListAsync(t));}
[HttpPost] public async Task<ActionResult> Create(Guid academyId,CreateWorkItem r,CancellationToken t){if(string.IsNullOrWhiteSpace(r.Type)||string.IsNullOrWhiteSpace(r.Title))return BadRequest();var x=new AdminWorkItem{AcademyId=academyId,Type=r.Type.Trim(),Title=r.Title.Trim(),Description=r.Description?.Trim(),Priority=string.IsNullOrWhiteSpace(r.Priority)?"Normal":r.Priority.Trim(),EntityType=r.EntityType?.Trim(),EntityId=r.EntityId,DueAtUtc=r.DueAtUtc};db.AdminWorkItems.Add(x);await db.SaveChangesAsync(t);return Ok(x);}
[HttpPatch("{id:guid}/status")] public async Task<ActionResult> Status(Guid academyId,Guid id,WorkStatus r,CancellationToken t){var x=await db.AdminWorkItems.SingleOrDefaultAsync(x=>x.AcademyId==academyId&&x.Id==id,t);if(x is null)return NotFound();if(r.Status is not("Open"or"InProgress"or"Completed"or"Cancelled"))return BadRequest();x.Status=r.Status;x.CompletedAtUtc=r.Status=="Completed"?DateTime.UtcNow:null;await db.SaveChangesAsync(t);return Ok(x);}}
public sealed record CreateWorkItem(string Type,string Title,string? Description,string? Priority,string? EntityType,Guid? EntityId,DateTime? DueAtUtc); public sealed record WorkStatus(string Status);
